const kg=n=>`${new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(Number(n||0))} kg`;
let session=null,profile=null,page='dashboard',activity='ALL',year='ALL',C={},A=[],Y=[];
const menus=[['Pilotage',[['dashboard','Tableau de bord'],['alertes','Alertes & contrôle']]],['Production',[['planteurs','Planteurs / producteurs'],['commis','Commis & performance'],['localites','Localités & tarifs'],['collectes','Collectes & pesées'],['lots','Lots & traçabilité'],['stock','Stock & inventaire']]],['Trésorerie',[['caisse','Caisse'],['banques','Banques & transferts'],['echeances','Créances & dettes']]],['Logistique',[['transport','Transport & voyages'],['flotte','Flotte & maintenance'],['usines','Usines / clients']]],['Commercial',[['ventes','Ventes & règlements'],['depenses','Dépenses']]],['Comptabilité',[['compta','Comptabilité'],['clotures','Clôtures & reports']]],['Coopérative',[['membres','Membres & parts sociales'],['gouvernance','Gouvernance & AG'],['personnel','Personnel / utilisateurs'],['documents','Documents & conformité']]],['Contrôle',[['rapports','Rapports'],['audit','Audit'],['parametres','Paramètres']]]];
