const dateField={collectes:'date_collecte',paiements_planteurs:'date_paiement',chargements:'date_depart',ventes_usine:'date_vente',depenses:'date_depense',mouvements_caisse:'date_mouvement',voyages:'date_depart',mouvements_stock:'date_mouvement',echeances:'created_at',alertes:'created_at',lots:'date_ouverture',assemblees:'date_assemblee',maintenance_flotte:'date_operation'};
const toast=m=>{const t=$('#toast');t.textContent=m;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2800)};
const activityName=()=>activity==='ALL'?'Toutes activités':A.find(x=>x.id===activity)?.nom||'Activité';
const yearName=()=>year==='ALL'?'Toutes années':Y.find(x=>String(x.annee)===String(year))?.libelle||String(year);
const currentActivity=()=>activity==='ALL'?(A[0]?.id||null):activity, currentYear=()=>year==='ALL'?new Date().getFullYear():Number(year);
function inScope(row,table){if(activity!=='ALL'&&'activite_id' in row&&row.activite_id!==activity)return false;if(year!=='ALL'){if(row.exercice_annee!=null&&String(row.exercice_annee)!==String(year))return false;const f=dateField[table];if(row.exercice_annee==null&&f&&row[f]&&new Date(row[f]).getFullYear()!==Number(year))return false}return true}
const filt=(t,rows)=> (rows||[]).filter(r=>inScope(r,t));
async function q(t){const {data,error}=await sb.from(t).select('*').limit(5000);if(error){console.warn(t,error.message);return []}return data||[]}
async function load(){ $('#syncBadge').textContent='● Synchronisation';$('#syncBadge').className='badge warn';const vals=await Promise.all(loadTables.map(q));C=Object.fromEntries(loadTables.map((n,i)=>[n,vals[i]]));A=C.activites||[];Y=(C.exercices||[]).sort((a,b)=>b.annee-a.annee);$('#syncBadge').textContent='● En ligne';$('#syncBadge').className='badge ok'}
function nav(){ $('#nav').innerHTML=menus.map(([s,it])=>`<div class="nav-section">${s}</div>${it.map(([k,v])=>`<button class="nav-btn ${page===k?'active':''}" data-page="${k}">${v}</button>`).join('')}`).join('');document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();$('#sidebar').classList.remove('open')})}
const kpi=(l,v,s='')=>`<div class="kpi"><div class="label">${l}</div><div class="value">${v}</div><div class="sub">${s}</div></div>`;
const panel=(t,b,a='')=>`<div class="panel"><div class="panel-head"><h3>${t}</h3>${a}</div><div class="panel-body">${b}</div></div>`;
const table=(h,rows)=>`<div class="table-wrap"><table class="table"><thead><tr>${h.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows||`<tr><td colspan="${h.length}" class="empty">Aucune donnée</td></tr>`}</tbody></table></div>`;
const banner=()=>`<div class="year-banner"><div><strong>${esc(yearName())}</strong><div class="muted">${esc(activityName())}</div></div><span class="pill green">Base Supabase connectée</span></div>`;
const opt=(rows,fn)=>rows.map(x=>`<option value="${x.id}">${esc(fn(x))}</option>`).join('');
async function insert(t,p){const {error}=await sb.from(t).insert(p);if(error){toast('Erreur : '+error.message);return false}toast('Enregistré');await load();render();return true}
async function update(t,id,p){const {error}=await sb.from(t).update(p).eq('id',id);if(error){toast('Erreur : '+error.message);return false}toast('Mise à jour effectuée');await load();render();return true}
function dashboard(){const col=filt('collectes',C.collectes),ven=filt('ventes_usine',C.ventes_usine),dep=filt('depenses',C.depenses),ms=filt('mouvements_stock',C.mouvements_stock),pay=filt('paiements_planteurs',C.paiements_planteurs);const poids=col.reduce((s,x)=>s+Number(x.poids_net_kg||0),0),achat=col.reduce((s,x)=>s+Number(x.net_a_payer||0),0),ca=ven.reduce((s,x)=>s+Number(x.chiffre_affaires||0),0),charges=dep.reduce((s,x)=>s+Number(x.montant||0),0),stock=ms.reduce((s,x)=>s+(x.type_mouvement==='sortie'?-1:1)*Number(x.poids_kg||0),0),paid=pay.reduce((s,x)=>s+Number(x.montant||0),0);const alerts=(C.alertes||[]).filter(x=>!x.resolu).slice(0,8).map(x=>`<tr><td>${esc(x.niveau||'info')}</td><td>${esc(x.titre)}</td><td>${esc(x.message)}</td></tr>`).join('');return banner()+`<div class="grid kpis">${kpi('Collecté',kg(poids),'Poids net')}${kpi('Stock théorique',kg(stock),'Entrées - sorties')}${kpi('Chiffre d’affaires',money(ca),'Ventes usine')}${kpi('Résultat opérationnel',money(ca-achat-charges),'CA - achats - dépenses')}</div><div class="grid two">${panel('Situation financière',`<div class="metric"><span>Achats planteurs</span><strong>${money(achat)}</strong></div><div class="metric"><span>Paiements effectués</span><strong>${money(paid)}</strong></div><div class="metric"><span>Dépenses</span><strong>${money(charges)}</strong></div><div class="metric"><span>Ventes</span><strong>${money(ca)}</strong></div>`)}${panel('Alertes ouvertes',table(['Niveau','Titre','Message'],alerts))}</div>`}
function simpleList(title,headers,rows,form=''){return banner()+`<div class="grid ${form?'two':''}">${panel(title,table(headers,rows))}${form?panel('Nouvelle saisie',form):''}</div>`}
function planteurs(){const rows=filt('planteurs',C.planteurs).map(x=>`<tr><td>${esc(x.code_planteur)}</td><td>${esc((x.nom||'')+' '+(x.prenoms||''))}</td><td>${esc(x.telephone||'')}</td><td>${esc(C.localites.find(l=>l.id===x.localite_id)?.nom||'—')}</td><td>${x.actif?'Actif':'Inactif'}</td></tr>`).join('');const f=`<form id="fPlanteur"><label>Code<input name="code" required placeholder="PL-0001"></label><label>Nom<input name="nom" required></label><label>Prénoms<input name="prenoms"></label><label>Téléphone<input name="telephone"></label><label>Localité<select name="localite"><option value="">—</option>${opt(C.localites,x=>x.nom)}</select></label><label>Village / campement<input name="village"></label><button class="btn primary wide">Enregistrer</button></form>`;return simpleList('Planteurs / producteurs',['Code','Nom','Téléphone','Localité','Statut'],rows,f)}
function commis(){const rows=filt('commis',C.commis).map(x=>`<tr><td>${esc(x.code_commis)}</td><td>${esc((x.nom||'')+' '+(x.prenoms||''))}</td><td>${esc(x.telephone||'')}</td><td>${esc(x.zone_principale||'—')}</td><td>${filt('collectes',C.collectes).filter(c=>c.commis_id===x.id).length}</td></tr>`).join('');const f=`<form id="fCommis"><label>Code<input name="code" required></label><label>Nom<input name="nom" required></label><label>Prénoms<input name="prenoms"></label><label>Téléphone<input name="telephone"></label><label>Zone principale<input name="zone"></label><button class="btn primary wide">Enregistrer</button></form>`;return simpleList('Commis & performance',['Code','Nom','Téléphone','Zone','Collectes'],rows,f)}
function localites(){const lr=filt('localites',C.localites).map(x=>`<tr><td>${esc(x.nom)}</td><td>${esc(x.zone||'')}</td><td>${esc(x.sous_prefecture||'')}</td><td>${x.distance_site_km??'—'}</td></tr>`).join(''),tr=filt('tarifs_bord_champ',C.tarifs_bord_champ).map(x=>`<tr><td>${esc(C.localites.find(l=>l.id===x.localite_id)?.nom||'—')}</td><td>${money(x.prix_kg)}/kg</td><td>${esc(x.date_debut)}</td><td>${x.actif?'Actif':'Clos'}</td></tr>`).join('');return banner()+`<div class="grid two">${panel('Localités',table(['Localité','Zone','Sous-préfecture','Distance km'],lr))}${panel('Tarifs bord champ',table(['Localité','Prix/kg','Début','Statut'],tr))}</div><div class="grid two" style="margin-top:16px">${panel('Ajouter une localité',`<form id="fLocalite"><label>Nom<input name="nom" required></label><label>Zone<input name="zone"></label><label>Sous-préfecture<input name="sp"></label><label>Distance site km<input name="distance" type="number" step="0.1"></label><button class="btn primary wide">Enregistrer</button></form>`)}${panel('Nouveau tarif',`<form id="fTarif"><label>Code<input name="code" required></label><label>Localité<select name="localite" required>${opt(C.localites,x=>x.nom)}</select></label><label>Prix/kg<input name="prix" type="number" step="0.01" required></label><label>Date début<input name="date" type="date" required></label><button class="btn primary wide">Créer le tarif</button></form>`)}</div>`}
function collectes(){const rows=filt('collectes',C.collectes).sort((a,b)=>new Date(b.date_collecte)-new Date(a.date_collecte)).map(x=>`<tr><td>${esc(x.numero_recu)}</td><td>${new Date(x.date_collecte).toLocaleDateString('fr-FR')}</td><td>${esc(C.planteurs.find(p=>p.id===x.planteur_id)?.nom||'—')}</td><td>${kg(x.poids_net_kg)}</td><td>${money(x.net_a_payer)}</td><td>${esc(x.statut_paiement)}</td></tr>`).join('');const f=`<form id="fCollecte"><label>N° reçu<input name="recu" required></label><label>Date<input name="date" type="datetime-local" required></label><label>Planteur<select name="planteur" required>${opt(filt('planteurs',C.planteurs),x=>(x.code_planteur+' • '+x.nom))}</select></label><label>Commis<select name="commis" required>${opt(filt('commis',C.commis),x=>x.nom)}</select></label><label>Localité<select name="localite" required>${opt(filt('localites',C.localites),x=>x.nom)}</select></label><label>Tarif<select name="tarif" required>${opt(filt('tarifs_bord_champ',C.tarifs_bord_champ).filter(x=>x.actif),x=>money(x.prix_kg)+'/kg')}</select></label><label>Poids brut kg<input name="brut" type="number" step="0.01" required></label><label>Tare kg<input name="tare" type="number" step="0.01" value="0"></label><button class="btn primary wide">Valider la pesée</button></form>`;return simpleList('Collectes & pesées',['Reçu','Date','Planteur','Poids net','Net à payer','Paiement'],rows,f)}
function lots(){const rows=filt('lots',C.lots).map(x=>`<tr><td>${esc(x.numero_lot)}</td><td>${esc(C.localites.find(l=>l.id===x.localite_id)?.nom||'—')}</td><td>${kg(x.poids_total_kg)}</td><td>${money(x.cout_achat_total)}</td><td>${esc(x.statut||'')}</td></tr>`).join('');return simpleList('Lots & traçabilité',['Lot','Localité','Poids','Coût achat','Statut'],rows,`<form id="fLot"><label>N° lot<input name="numero" required></label><label>Localité<select name="localite"><option value="">—</option>${opt(C.localites,x=>x.nom)}</select></label><label>Commis<select name="commis"><option value="">—</option>${opt(C.commis,x=>x.nom)}</select></label><button class="btn primary wide">Ouvrir le lot</button></form>`)}
