function ventes(){const v=filt('ventes_usine',C.ventes_usine),r=C.reglements_usine;const rows=v.map(x=>`<tr><td>${esc(x.numero_vente)}</td><td>${esc(C.usines.find(u=>u.id===x.usine_id)?.nom||'—')}</td><td>${kg(x.poids_facture_kg)}</td><td>${money(x.chiffre_affaires)}</td><td>${money(x.benefice_estime)}</td><td>${esc(x.statut_reglement)}</td></tr>`).join(''),rr=r.map(x=>`<tr><td>${esc(v.find(v=>v.id===x.vente_id)?.numero_vente||'—')}</td><td>${money(x.montant)}</td><td>${esc(x.moyen_paiement)}</td><td>${esc(x.reference_paiement||'')}</td></tr>`).join('');return banner()+`<div class="grid two">${panel('Ventes usine',table(['Vente','Usine','Poids','CA','Bénéfice','Règlement'],rows))}${panel('Règlements reçus',table(['Vente','Montant','Moyen','Référence'],rr))}</div>`}
function depenses(){const rows=filt('depenses',C.depenses).map(x=>`<tr><td>${esc(x.numero_depense)}</td><td>${new Date(x.date_depense).toLocaleDateString('fr-FR')}</td><td>${esc(x.categorie)}</td><td>${esc(x.libelle)}</td><td>${money(x.montant)}</td><td>${esc(x.beneficiaire||'')}</td></tr>`).join('');const f=`<form id="fDepense"><label>N° dépense<input name="numero" required></label><label>Catégorie<input name="categorie" required></label><label>Libellé<input name="libelle" required></label><label>Montant<input name="montant" type="number" required></label><label>Bénéficiaire<input name="beneficiaire"></label><label>Moyen de paiement<select name="moyen"><option value="especes">Espèces</option><option value="banque">Banque</option><option value="mobile_money">Mobile Money</option></select></label><button class="btn primary wide">Enregistrer</button></form>`;return simpleList('Dépenses',['N°','Date','Catégorie','Libellé','Montant','Bénéficiaire'],rows,f)}
function compta(){const p=C.pieces_comptables,e=C.ecritures_comptables;const debit=e.reduce((s,x)=>s+Number(x.debit||0),0),credit=e.reduce((s,x)=>s+Number(x.credit||0),0);return banner()+`<div class="grid kpis">${kpi('Pièces comptables',p.length)}${kpi('Total débit',money(debit))}${kpi('Total crédit',money(credit))}${kpi('Équilibre',money(debit-credit),debit===credit?'Équilibré':'À contrôler')}</div><div class="grid two">${panel('Pièces récentes',table(['N°','Date','Libellé','Statut'],p.slice(-30).reverse().map(x=>`<tr><td>${esc(x.numero_piece)}</td><td>${esc(x.date_piece||'')}</td><td>${esc(x.libelle)}</td><td>${esc(x.statut||'')}</td></tr>`).join('')))}${panel('Plan comptable',table(['Compte','Intitulé','Classe','Type'],C.comptes_comptables.map(x=>`<tr><td>${esc(x.numero)}</td><td>${esc(x.intitule)}</td><td>${esc(x.classe||'')}</td><td>${esc(x.type_compte||'')}</td></tr>`).join('')))}</div>`}
function clotures(){const ex=C.exercices.map(x=>`<tr><td>${x.annee}</td><td>${esc(x.libelle)}</td><td>${esc(x.date_debut)}</td><td>${esc(x.date_fin)}</td><td>${esc(x.statut)}</td></tr>`).join(''),rp=C.reports_a_nouveau.map(x=>`<tr><td>${x.exercice_source}</td><td>${x.exercice_destination}</td><td>${esc(x.type_report)}</td><td>${money(x.valeur_numeric)}</td></tr>`).join('');return banner()+`<div class="grid two">${panel('Exercices',table(['Année','Libellé','Début','Fin','Statut'],ex))}${panel('Reports à nouveau',table(['Source','Destination','Type','Valeur'],rp))}</div>`}
function membres(){const m=C.membres_cooperative.map(x=>`<tr><td>${esc(x.code_membre)}</td><td>${esc((x.nom||'')+' '+(x.prenoms||''))}</td><td>${esc(x.telephone||'')}</td><td>${x.nombre_parts||0}</td><td>${money(x.valeur_parts)}</td><td>${esc(x.statut||'')}</td></tr>`).join('');return banner()+`<div class="grid two">${panel('Membres',table(['Code','Nom','Téléphone','Parts','Valeur','Statut'],m))}${panel('Parts sociales',table(['Membre','Date','Type','Nb parts','Montant'],C.parts_sociales.map(x=>`<tr><td>${esc(C.membres_cooperative.find(m=>m.id===x.membre_id)?.nom||'—')}</td><td>${esc(x.date_operation||'')}</td><td>${esc(x.type_operation)}</td><td>${x.nombre_parts||0}</td><td>${money(x.montant)}</td></tr>`).join('')))}</div>`}
function gouvernance(){const rows=C.assemblees.map(x=>`<tr><td>${esc(x.type_assemblee)}</td><td>${esc(x.date_assemblee)}</td><td>${esc(x.lieu||'')}</td><td>${esc(x.statut||'')}</td><td>${x.pv_url?'<span class="status-ok">PV disponible</span>':'—'}</td></tr>`).join('');return simpleList('Gouvernance & assemblées',['Type','Date','Lieu','Statut','PV'],rows)}
function personnel(){const rows=C.profiles.map(x=>`<tr><td>${esc(x.nom_complet||'')}</td><td>${esc(x.telephone||'')}</td><td>${esc(x.role)}</td><td>${x.actif?'<span class="status-ok">Actif</span>':'<span class="status-bad">Inactif</span>'}</td></tr>`).join('');return simpleList('Utilisateurs & rôles',['Nom','Téléphone','Rôle','Statut'],rows)}
function documents(){return banner()+panel('Documents & conformité',`<div class="grid three"><div class="quick"><strong>Justificatifs dépenses</strong><span class="muted">${C.depenses.filter(x=>x.justificatif_url).length} document(s) référencé(s)</span></div><div class="quick"><strong>Tickets de pesée</strong><span class="muted">${C.voyages.filter(x=>x.ticket_pesee_url).length} document(s) référencé(s)</span></div><div class="quick"><strong>PV d’assemblée</strong><span class="muted">${C.assemblees.filter(x=>x.pv_url).length} document(s) référencé(s)</span></div></div><p class="muted" style="margin-top:16px">Ce module centralise les références de documents déjà stockées dans la base. Le stockage sécurisé peut être relié à Supabase Storage.</p>`)}
function alertes(){const a=C.alertes.map(x=>`<tr><td>${esc(x.niveau||'')}</td><td>${esc(x.type_alerte)}</td><td>${esc(x.titre)}</td><td>${esc(x.message)}</td><td>${x.resolu?'<span class="status-ok">Résolu</span>':'<span class="status-warn">Ouvert</span>'}</td></tr>`).join(''),i=C.incidents.map(x=>`<tr><td>${esc(x.gravite)}</td><td>${esc(x.type_incident)}</td><td>${esc(x.description)}</td><td>${esc(x.statut)}</td></tr>`).join('');return banner()+`<div class="grid two">${panel('Alertes',table(['Niveau','Type','Titre','Message','Statut'],a))}${panel('Incidents',table(['Gravité','Type','Description','Statut'],i))}</div>`}
function audit(){const rows=C.audit_logs.slice().sort((a,b)=>new Date(b.date_action)-new Date(a.date_action)).map(x=>`<tr><td>${new Date(x.date_action).toLocaleString('fr-FR')}</td><td>${esc(x.module)}</td><td>${esc(x.type_action)}</td><td>${esc(x.operation_id||'')}</td><td>${esc(x.motif||'')}</td></tr>`).join('');return simpleList('Journal d’audit',['Date','Module','Action','Opération','Motif'],rows)}
function rapports(){const col=filt('collectes',C.collectes),ven=filt('ventes_usine',C.ventes_usine),dep=filt('depenses',C.depenses);const byAct=A.map(a=>{const cc=col.filter(x=>x.activite_id===a.id),vv=ven.filter(x=>x.activite_id===a.id),dd=dep.filter(x=>x.activite_id===a.id);return `<tr><td>${esc(a.nom)}</td><td>${kg(cc.reduce((s,x)=>s+Number(x.poids_net_kg||0),0))}</td><td>${money(vv.reduce((s,x)=>s+Number(x.chiffre_affaires||0),0))}</td><td>${money(dd.reduce((s,x)=>s+Number(x.montant||0),0))}</td></tr>`}).join('');return banner()+panel('Synthèse par activité',table(['Activité','Collecté','CA','Dépenses'],byAct),`<button class="btn secondary" onclick="window.print()">Imprimer / PDF</button>`)+`<div class="grid three" style="margin-top:16px"><div class="quick"><strong>Collecte</strong><span class="muted">Analyse par activité, année, planteur, commis et localité.</span></div><div class="quick"><strong>Trésorerie</strong><span class="muted">Caisse, paiements, dépenses, banque et transferts.</span></div><div class="quick"><strong>Logistique</strong><span class="muted">Voyages, poids départ/arrivée, écarts et maintenance.</span></div></div>`}
function parametres(){return banner()+`<div class="grid two">${panel('Activités',table(['Code','Nom','Unité','Statut'],A.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.nom)}</td><td>${esc(x.unite_principale)}</td><td>${x.actif?'Actif':'Inactif'}</td></tr>`).join('')))}${panel('Caisses',table(['Code','Nom','Statut'],C.caisses.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.nom)}</td><td>${x.actif?'Actif':'Inactif'}</td></tr>`).join('')))}</div>`}
function render(){nav();$('#pageTitle').textContent=labels[page]||'SCC-CI-SCOOPS';$('#pageSubtitle').textContent=`${activityName()} • ${yearName()}`;const map={dashboard,alertes,planteurs,commis,localites,collectes,lots,stock,caisse,banques,echeances,transport,flotte,usines,ventes,depenses,compta,clotures,membres,gouvernance,personnel,documents,rapports,audit,parametres};$('#content').innerHTML=(map[page]||dashboard)();bindForms()}
function bind(id,fn){const el=$('#'+id);if(el)el.onsubmit=async e=>{e.preventDefault();await fn(new FormData(el))}}
function bindForms(){bind('fPlanteur',fd=>insert('planteurs',{code_planteur:fd.get('code'),nom:fd.get('nom'),prenoms:fd.get('prenoms')||null,telephone:fd.get('telephone')||null,localite_id:fd.get('localite')||null,village_campement:fd.get('village')||null,activite_id:currentActivity(),exercice_annee:currentYear(),actif:true}));bind('fCommis',fd=>insert('commis',{code_commis:fd.get('code'),nom:fd.get('nom'),prenoms:fd.get('prenoms')||null,telephone:fd.get('telephone')||null,zone_principale:fd.get('zone')||null,activite_id:currentActivity(),exercice_annee:currentYear(),actif:true}));bind('fLocalite',fd=>insert('localites',{nom:fd.get('nom'),zone:fd.get('zone')||null,sous_prefecture:fd.get('sp')||null,distance_site_km:Number(fd.get('distance')||0)||null,activite_id:currentActivity(),exercice_annee:currentYear(),actif:true}));bind('fTarif',fd=>insert('tarifs_bord_champ',{code_tarif:fd.get('code'),localite_id:fd.get('localite'),prix_kg:Number(fd.get('prix')),date_debut:fd.get('date'),activite_id:currentActivity(),exercice_annee:currentYear(),actif:true}));bind('fCollecte',fd=>{const tar=C.tarifs_bord_champ.find(x=>x.id===fd.get('tarif')),brut=Number(fd.get('brut')),tare=Number(fd.get('tare')||0),net=brut-tare,prix=Number(tar?.prix_kg||0);return insert('collectes',{numero_recu:fd.get('recu'),date_collecte:new Date(fd.get('date')).toISOString(),planteur_id:fd.get('planteur'),commis_id:fd.get('commis'),localite_id:fd.get('localite'),tarif_id:fd.get('tarif'),poids_brut_kg:brut,tare_kg:tare,poids_net_kg:net,prix_kg:prix,montant_brut:net*prix,retenue_avance:0,net_a_payer:net*prix,statut_paiement:'a_payer',activite_id:currentActivity(),exercice_annee:currentYear(),saisi_par:session.user.id})});bind('fLot',fd=>insert('lots',{numero_lot:fd.get('numero'),activite_id:currentActivity(),exercice_annee:currentYear(),localite_id:fd.get('localite')||null,commis_id:fd.get('commis')||null,statut:'ouvert'}));bind('fStock',fd=>insert('mouvements_stock',{activite_id:currentActivity(),exercice_annee:currentYear(),type_mouvement:fd.get('type'),poids_kg:Number(fd.get('poids')),commentaire:fd.get('commentaire')||null,created_by:session.user.id}));bind('fCaisse',fd=>insert('mouvements_caisse',{numero_piece:fd.get('piece'),activite_id:currentActivity(),exercice_annee:currentYear(),sens:fd.get('sens'),categorie:fd.get('categorie'),libelle:fd.get('libelle'),montant:Number(fd.get('montant')),mode_paiement:fd.get('mode'),statut:'valide',created_by:session.user.id}));bind('fVoyage',fd=>insert('voyages',{numero_voyage:fd.get('numero'),activite_id:currentActivity(),exercice_annee:currentYear(),camion_id:fd.get('camion')||null,usine_id:fd.get('usine')||null,chauffeur_nom:fd.get('chauffeur')||null,origine:fd.get('origine')||null,destination:fd.get('destination')||null,poids_depart_kg:Number(fd.get('poids')||0),statut:'preparation',created_by:session.user.id}));bind('fDepense',fd=>insert('depenses',{numero_depense:fd.get('numero'),date_depense:new Date().toISOString(),categorie:fd.get('categorie'),libelle:fd.get('libelle'),montant:Number(fd.get('montant')),beneficiaire:fd.get('beneficiaire')||null,moyen_paiement:fd.get('moyen'),activite_id:currentActivity(),exercice_annee:currentYear()}))}
async function enter(){const r=await sb.from('profiles').select('*').eq('id',session.user.id).single();if(r.error){toast('Profil utilisateur introuvable ou accès refusé');return}profile=r.data;await load();$('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#roleLabel').textContent=profile.role||'utilisateur';$('#userName').textContent=profile.nom_complet||'Utilisateur';$('#activitySelect').innerHTML='<option value="ALL">Toutes activités</option>'+A.map(a=>`<option value="${a.id}">${esc(a.nom)}</option>`).join('');const cy=new Date().getFullYear();$('#yearSelect').innerHTML='<option value="ALL">Toutes années</option>'+(Y.length?Y.map(y=>`<option value="${y.annee}">${esc(y.libelle||y.annee)}</option>`).join(''):`<option value="${cy}">${cy}</option>`);if(Y.some(y=>y.annee===cy)){year=String(cy);$('#yearSelect').value=year}$('#activitySelect').onchange=e=>{activity=e.target.value;render()};$('#yearSelect').onchange=e=>{year=e.target.value;render()};render()}
$('#loginForm').onsubmit=async e=>{e.preventDefault();$('#loginStatus').textContent='Connexion...';const {data,error}=await sb.auth.signInWithPassword({email:$('#loginEmail').value,password:$('#loginPassword').value});if(error){$('#loginStatus').textContent=error.message;return}session=data.session;$('#loginStatus').textContent='';await enter()};$('#logoutBtn').onclick=async()=>{await sb.auth.signOut();location.reload()};$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#refreshBtn').onclick=async()=>{await load();render();toast('Données actualisées')};(async()=>{$('#todayLabel').textContent=new Date().toLocaleDateString('fr-FR',{dateStyle:'full'});const {data:{session:s}}=await sb.auth.getSession();if(s){session=s;await enter()}})();
/* ===== V3.1 PRO — compléments métier, contrôle par rôles et formulaires avancés ===== */
const ROLE_PAGES={
  admin:'*',
  direction:'*',
  secretariat:['dashboard','alertes','planteurs','commis','localites','collectes','lots','membres','gouvernance','documents','rapports'],
  caisse:['dashboard','alertes','planteurs','collectes','caisse','echeances','rapports'],
  comptabilite:['dashboard','alertes','planteurs','commis','collectes','caisse','banques','echeances','transport','flotte','usines','ventes','depenses','compta','clotures','membres','documents','rapports','audit'],
  commis:['dashboard','planteurs','localites','collectes','lots','rapports'],
  stock_transport:['dashboard','alertes','localites','collectes','lots','stock','transport','flotte','usines','documents','rapports']
};
function canRole(...roles){return !!profile && (profile.role==='admin'||roles.includes(profile.role))}
function pageAllowed(k){const a=ROLE_PAGES[profile?.role||''];return a==='*'||(Array.isArray(a)&&a.includes(k))}
nav=function(){
  $('#nav').innerHTML=menus.map(([s,it])=>{const allowed=it.filter(([k])=>pageAllowed(k));if(!allowed.length)return '';return `<div class="nav-section">${s}</div>${allowed.map(([k,v])=>`<button class="nav-btn ${page===k?'active':''}" data-page="${k}">${v}</button>`).join('')}`}).join('');
  document.querySelectorAll('.nav-btn').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();$('#sidebar').classList.remove('open')})
};
const roleInfo=()=>`<div class="role-note">Connecté comme <strong>${esc(profile?.role||'utilisateur')}</strong>. Les actions disponibles sont limitées selon les responsabilités du poste.</div>`;
const formPanel=(title,id,body,allowed=true)=>allowed?panel(title,`<form id="${id}" class="form-grid">${body}</form>`):panel(title,`<div class="section-note">Votre rôle peut consulter ce module mais ne peut pas créer d'opération ici.</div>`);
const dtLocal=()=>{const d=new Date();d.setMinutes(d.getMinutes()-d.getTimezoneOffset());return d.toISOString().slice(0,16)};

const _dashboard=dashboard;
dashboard=function(){return roleInfo()+_dashboard()}

caisse=function(){
 const rows=filt('mouvements_caisse',C.mouvements_caisse).slice().sort((a,b)=>new Date(b.date_mouvement||b.created_at)-new Date(a.date_mouvement||a.created_at));
 const entrees=rows.filter(x=>x.sens==='entree').reduce((s,x)=>s+Number(x.montant||0),0),sorties=rows.filter(x=>x.sens==='sortie').reduce((s,x)=>s+Number(x.montant||0),0);
 const tr=rows.map(x=>`<tr><td>${esc(x.numero_piece)}</td><td>${new Date(x.date_mouvement||x.created_at).toLocaleString('fr-FR')}</td><td>${esc(x.sens)}</td><td>${esc(x.categorie)}</td><td>${esc(x.libelle)}</td><td>${money(x.montant)}</td><td>${esc(x.mode_paiement||'')}</td><td>${esc(x.statut||'')}</td></tr>`).join('');
 const f=formPanel('Nouveau mouvement','fCaisse',`<label>Pièce<input name="piece" required placeholder="CAI-2026-0001"></label><label>Sens<select name="sens"><option value="entree">Entrée</option><option value="sortie">Sortie</option></select></label><label>Catégorie<input name="categorie" required placeholder="Paiement planteur, retrait, avance..."></label><label>Mode<select name="mode"><option>Caisse</option><option>Banque</option><option>Orange Money</option><option>Wave</option><option>MTN Money</option></select></label><label class="span2">Libellé<input name="libelle" required></label><label>Montant<input name="montant" type="number" min="0" required></label><button class="btn primary wide">Enregistrer le mouvement</button>`,canRole('direction','caisse'));
 const unpaid=filt('collectes',C.collectes).filter(x=>x.statut_paiement!=='paye').map(x=>`<tr><td>${esc(x.numero_recu)}</td><td>${esc((C.planteurs.find(p=>p.id===x.planteur_id)?.nom)||'—')}</td><td>${money(x.net_a_payer)}</td><td><button class="btn secondary" data-pay="${x.id}">Payer</button></td></tr>`).join('');
 return roleInfo()+banner()+`<div class="grid kpis">${kpi('Entrées',money(entrees))}${kpi('Sorties',money(sorties))}${kpi('Solde théorique',money(entrees-sorties))}${kpi('Collectes à payer',String(filt('collectes',C.collectes).filter(x=>x.statut_paiement!=='paye').length))}</div><div class="grid two">${panel('Journal de caisse',table(['Pièce','Date','Sens','Catégorie','Libellé','Montant','Mode','Statut'],tr))}${f}</div><div style="margin-top:16px">${panel('Paiements planteurs en attente',table(['Reçu','Planteur','Net à payer','Action'],unpaid))}</div>`
};

banques=function(){
 const b=C.comptes_bancaires.map(x=>`<tr><td>${esc(x.banque)}</td><td>${esc(x.libelle_compte)}</td><td>${esc(x.numero_masque||'')}</td><td>${x.actif===false?'Inactif':'Actif'}</td></tr>`).join('');
 const t=filt('transferts_tresorerie',C.transferts_tresorerie).map(x=>`<tr><td>${new Date(x.date_transfert||x.created_at).toLocaleString('fr-FR')}</td><td>${esc(x.source_type||'')}</td><td>${esc(x.destination_type||'')}</td><td>${money(x.montant)}</td><td>${esc(x.reference||'')}</td><td>${esc(x.statut||'')}</td></tr>`).join('');
 const add=formPanel('Ajouter un compte bancaire','fBanque',`<label>Banque<input name="banque" required></label><label>Libellé<input name="libelle" required></label><label>Numéro masqué<input name="numero" placeholder="****1234"></label><button class="btn primary wide">Ajouter</button>`,canRole('direction','comptabilite'));
 const trans=formPanel('Nouveau transfert','fTransfert',`<label>Source<select name="source"><option value="caisse">Caisse</option><option value="banque">Banque</option></select></label><label>Destination<select name="destination"><option value="banque">Banque</option><option value="caisse">Caisse</option></select></label><label>Montant<input name="montant" type="number" min="0" required></label><label>Référence<input name="reference"></label><button class="btn primary wide">Enregistrer</button>`,canRole('direction','comptabilite'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Comptes bancaires',table(['Banque','Compte','Numéro','Statut'],b))}${add}</div><div class="grid two" style="margin-top:16px">${panel('Transferts de trésorerie',table(['Date','Source','Destination','Montant','Référence','Statut'],t))}${trans}</div>`
};

flotte=function(){
 const c=C.camions.map(x=>`<tr><td>${esc(x.immatriculation)}</td><td>${esc(x.chauffeur||'')}</td><td>${esc(x.telephone_chauffeur||'')}</td><td>${kg(x.capacite_kg)}</td><td>${x.actif?'Actif':'Inactif'}</td></tr>`).join('');
 const m=C.maintenance_flotte.map(x=>`<tr><td>${esc(C.camions.find(c=>c.id===x.camion_id)?.immatriculation||'—')}</td><td>${esc(x.date_operation||'')}</td><td>${esc(x.type_operation)}</td><td>${money(x.cout)}</td><td>${esc(x.prochaine_echeance||'')}</td></tr>`).join('');
 const cf=formPanel('Ajouter un camion','fCamion',`<label>Immatriculation<input name="immat" required></label><label>Chauffeur<input name="chauffeur"></label><label>Téléphone<input name="telephone"></label><label>Capacité kg<input name="capacite" type="number" min="0"></label><button class="btn primary wide">Ajouter le camion</button>`,canRole('direction','stock_transport'));
 const mf=formPanel('Enregistrer une maintenance','fMaintenance',`<label>Camion<select name="camion" required>${opt(C.camions,x=>x.immatriculation)}</select></label><label>Date<input type="date" name="date" required></label><label>Type<input name="type" required placeholder="Vidange, pneus, réparation..."></label><label>Coût<input name="cout" type="number" min="0"></label><label>Prestataire<input name="prestataire"></label><label>Prochaine échéance<input type="date" name="echeance"></label><button class="btn primary wide">Enregistrer</button>`,canRole('direction','stock_transport'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Parc camions',table(['Immatriculation','Chauffeur','Téléphone','Capacité','Statut'],c))}${cf}</div><div class="grid two" style="margin-top:16px">${panel('Historique maintenance',table(['Camion','Date','Opération','Coût','Prochaine échéance'],m))}${mf}</div>`
};

usines=function(){
 const r=C.usines.map(x=>`<tr><td>${esc(x.nom)}</td><td>${esc(x.localisation||'')}</td><td>${esc(x.contact||'')}</td><td>${esc(x.telephone||'')}</td><td>${x.actif?'Actif':'Inactif'}</td></tr>`).join('');
 const f=formPanel('Ajouter une usine / client','fUsine',`<label>Nom<input name="nom" required></label><label>Localisation<input name="localisation"></label><label>Contact<input name="contact"></label><label>Téléphone<input name="telephone"></label><button class="btn primary wide">Ajouter</button>`,canRole('direction','stock_transport'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Usines / clients',table(['Nom','Localisation','Contact','Téléphone','Statut'],r))}${f}</div>`
};

ventes=function(){
 const v=filt('ventes_usine',C.ventes_usine).map(x=>`<tr><td>${esc(x.numero_vente)}</td><td>${esc(C.usines.find(u=>u.id===x.usine_id)?.nom||'—')}</td><td>${kg(x.poids_facture_kg)}</td><td>${money(x.prix_vente_kg)}/kg</td><td>${money(x.chiffre_affaires)}</td><td>${money(x.benefice_estime)}</td><td>${esc(x.statut_reglement)}</td></tr>`).join('');
 const r=C.reglements_usine.map(x=>`<tr><td>${new Date(x.date_reglement).toLocaleDateString('fr-FR')}</td><td>${esc(C.ventes_usine.find(v=>v.id===x.vente_id)?.numero_vente||'—')}</td><td>${money(x.montant)}</td><td>${esc(x.moyen_paiement)}</td><td>${esc(x.reference_paiement||'')}</td></tr>`).join('');
 const vf=formPanel('Nouvelle vente','fVente',`<label>N° vente<input name="numero" required placeholder="VTE-2026-0001"></label><label>Chargement<select name="chargement" required>${opt(C.chargements,x=>x.numero_chargement)}</select></label><label>Usine<select name="usine" required>${opt(C.usines,x=>x.nom)}</select></label><label>Poids facturé kg<input name="poids" type="number" step="0.01" min="0" required></label><label>Prix vente / kg<input name="prix" type="number" min="0" required></label><label>Coût achats planteurs<input name="cout" type="number" min="0" value="0"></label><label>Autres charges<input name="charges" type="number" min="0" value="0"></label><button class="btn primary wide">Enregistrer la vente</button>`,canRole('direction','comptabilite'));
 const rf=formPanel('Nouveau règlement usine','fReglement',`<label>Vente<select name="vente" required>${opt(C.ventes_usine,x=>x.numero_vente)}</select></label><label>Montant<input name="montant" type="number" min="0" required></label><label>Moyen<select name="moyen"><option>Banque</option><option>Chèque</option><option>Virement</option><option>Espèces</option></select></label><label>Référence<input name="reference"></label><button class="btn primary wide">Enregistrer le règlement</button>`,canRole('direction','comptabilite'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Ventes usine',table(['N°','Usine','Poids','Prix','CA','Bénéfice','Règlement'],v))}${vf}</div><div class="grid two" style="margin-top:16px">${panel('Règlements reçus',table(['Date','Vente','Montant','Moyen','Référence'],r))}${rf}</div>`
};

membres=function(){
 const m=C.membres_cooperative.map(x=>`<tr><td>${esc(x.code_membre)}</td><td>${esc((x.nom||'')+' '+(x.prenoms||''))}</td><td>${esc(x.telephone||'')}</td><td>${x.nombre_parts||0}</td><td>${money(x.valeur_parts)}</td><td>${esc(x.statut||'')}</td></tr>`).join('');
 const p=C.parts_sociales.map(x=>`<tr><td>${esc(C.membres_cooperative.find(m=>m.id===x.membre_id)?.nom||'—')}</td><td>${esc(x.date_operation||'')}</td><td>${esc(x.type_operation)}</td><td>${x.nombre_parts||0}</td><td>${money(x.montant)}</td></tr>`).join('');
 const mf=formPanel('Nouveau membre','fMembre',`<label>Code membre<input name="code" required></label><label>Nom<input name="nom" required></label><label>Prénoms<input name="prenoms"></label><label>Téléphone<input name="telephone"></label><label>Localité<select name="localite"><option value="">—</option>${opt(C.localites,x=>x.nom)}</select></label><label>Statut<select name="statut"><option>actif</option><option>suspendu</option><option>sorti</option></select></label><button class="btn primary wide">Enregistrer le membre</button>`,canRole('direction','secretariat'));
 const pf=formPanel('Opération sur parts sociales','fPart',`<label>Membre<select name="membre" required>${opt(C.membres_cooperative,x=>(x.code_membre+' • '+x.nom))}</select></label><label>Type<select name="type"><option>souscription</option><option>achat</option><option>cession</option><option>remboursement</option></select></label><label>Nombre de parts<input name="nombre" type="number" step="0.01" min="0"></label><label>Montant<input name="montant" type="number" min="0"></label><label>Référence<input name="reference"></label><button class="btn primary wide">Enregistrer</button>`,canRole('direction','secretariat','comptabilite'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Membres',table(['Code','Nom','Téléphone','Parts','Valeur','Statut'],m))}${mf}</div><div class="grid two" style="margin-top:16px">${panel('Parts sociales',table(['Membre','Date','Type','Nb parts','Montant'],p))}${pf}</div>`
};

gouvernance=function(){
 const rows=C.assemblees.map(x=>`<tr><td>${esc(x.type_assemblee)}</td><td>${esc(x.date_assemblee)}</td><td>${esc(x.lieu||'')}</td><td>${esc(x.statut||'')}</td><td>${x.pv_url?'<span class="status-ok">PV disponible</span>':'—'}</td></tr>`).join('');
 const f=formPanel('Nouvelle assemblée','fAssemblee',`<label>Type<select name="type"><option>AGO</option><option>AGE</option><option>Conseil</option><option>Réunion bureau</option></select></label><label>Date<input name="date" type="date" required></label><label>Lieu<input name="lieu"></label><label>Statut<select name="statut"><option>planifiee</option><option>tenue</option><option>reportee</option></select></label><label class="span2">Ordre du jour<textarea name="ordre"></textarea></label><button class="btn primary wide">Enregistrer</button>`,canRole('direction','secretariat'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Gouvernance & assemblées',table(['Type','Date','Lieu','Statut','PV'],rows))}${f}</div>`
};

compta=function(){
 const pc=filt('pieces_comptables',C.pieces_comptables).map(x=>`<tr><td>${esc(x.numero_piece)}</td><td>${esc(x.date_piece||'')}</td><td>${esc(C.journaux_comptables.find(j=>j.id===x.journal_id)?.code||'—')}</td><td>${esc(x.libelle)}</td><td>${esc(x.statut||'')}</td></tr>`).join('');
 const ec=C.ecritures_comptables.map(x=>`<tr><td>${esc(C.pieces_comptables.find(p=>p.id===x.piece_id)?.numero_piece||'—')}</td><td>${esc(C.comptes_comptables.find(c=>c.id===x.compte_id)?.numero||'—')}</td><td>${esc(x.libelle||'')}</td><td>${money(x.debit)}</td><td>${money(x.credit)}</td></tr>`).join('');
 const pf=formPanel('Nouvelle pièce comptable','fPiece',`<label>N° pièce<input name="numero" required></label><label>Journal<select name="journal" required>${opt(C.journaux_comptables,x=>x.code+' • '+x.nom)}</select></label><label>Date<input name="date" type="date" required></label><label>Libellé<input name="libelle" required></label><label>Référence source<input name="reference"></label><button class="btn primary wide">Créer la pièce</button>`,canRole('direction','comptabilite'));
 const ef=formPanel('Nouvelle écriture','fEcriture',`<label>Pièce<select name="piece" required>${opt(C.pieces_comptables,x=>x.numero_piece)}</select></label><label>Compte<select name="compte" required>${opt(C.comptes_comptables,x=>x.numero+' • '+x.intitule)}</select></label><label>Libellé<input name="libelle"></label><label>Débit<input name="debit" type="number" min="0" value="0"></label><label>Crédit<input name="credit" type="number" min="0" value="0"></label><button class="btn primary wide">Enregistrer l'écriture</button>`,canRole('direction','comptabilite'));
 return roleInfo()+banner()+`<div class="grid two">${panel('Pièces comptables',table(['Pièce','Date','Journal','Libellé','Statut'],pc))}${pf}</div><div class="grid two" style="margin-top:16px">${panel('Écritures',table(['Pièce','Compte','Libellé','Débit','Crédit'],ec))}${ef}</div>`
};

const _bindFormsV3=bindForms;
bindForms=function(){
  _bindFormsV3();
  bind('fBanque',fd=>insert('comptes_bancaires',{banque:fd.get('banque'),libelle_compte:fd.get('libelle'),numero_masque:fd.get('numero')||null,actif:true}));
  bind('fTransfert',fd=>insert('transferts_tresorerie',{activite_id:currentActivity(),exercice_annee:currentYear(),date_transfert:new Date().toISOString(),source_type:fd.get('source'),destination_type:fd.get('destination'),montant:Number(fd.get('montant')),reference:fd.get('reference')||null,statut:'valide',created_by:session.user.id}));
  bind('fCamion',fd=>insert('camions',{immatriculation:fd.get('immat'),chauffeur:fd.get('chauffeur')||null,telephone_chauffeur:fd.get('telephone')||null,capacite_kg:Number(fd.get('capacite')||0)||null,actif:true}));
  bind('fMaintenance',fd=>insert('maintenance_flotte',{camion_id:fd.get('camion'),exercice_annee:currentYear(),date_operation:fd.get('date'),type_operation:fd.get('type'),cout:Number(fd.get('cout')||0),prestataire:fd.get('prestataire')||null,prochaine_echeance:fd.get('echeance')||null}));
  bind('fUsine',fd=>insert('usines',{nom:fd.get('nom'),localisation:fd.get('localisation')||null,contact:fd.get('contact')||null,telephone:fd.get('telephone')||null,actif:true}));
  bind('fVente',fd=>{const poids=Number(fd.get('poids')),prix=Number(fd.get('prix')),cout=Number(fd.get('cout')||0),charges=Number(fd.get('charges')||0),ca=poids*prix;return insert('ventes_usine',{numero_vente:fd.get('numero'),chargement_id:fd.get('chargement'),usine_id:fd.get('usine'),poids_facture_kg:poids,prix_vente_kg:prix,chiffre_affaires:ca,cout_achat_planteurs:cout,autres_charges:charges,benefice_estime:ca-cout-charges,statut_reglement:'non_paye',activite_id:currentActivity(),exercice_annee:currentYear()})});
  bind('fReglement',fd=>insert('reglements_usine',{vente_id:fd.get('vente'),montant:Number(fd.get('montant')),moyen_paiement:fd.get('moyen'),reference_paiement:fd.get('reference')||null,date_reglement:new Date().toISOString()}));
  bind('fMembre',fd=>insert('membres_cooperative',{code_membre:fd.get('code'),nom:fd.get('nom'),prenoms:fd.get('prenoms')||null,telephone:fd.get('telephone')||null,localite_id:fd.get('localite')||null,date_adhesion:new Date().toISOString().slice(0,10),statut:fd.get('statut'),nombre_parts:0,valeur_parts:0}));
  bind('fPart',fd=>insert('parts_sociales',{membre_id:fd.get('membre'),exercice_annee:currentYear(),date_operation:new Date().toISOString().slice(0,10),type_operation:fd.get('type'),nombre_parts:Number(fd.get('nombre')||0),montant:Number(fd.get('montant')||0),reference:fd.get('reference')||null}));
  bind('fAssemblee',fd=>insert('assemblees',{exercice_annee:currentYear(),type_assemblee:fd.get('type'),date_assemblee:fd.get('date'),lieu:fd.get('lieu')||null,ordre_du_jour:fd.get('ordre')||null,statut:fd.get('statut')}));
  bind('fPiece',fd=>insert('pieces_comptables',{numero_piece:fd.get('numero'),journal_id:fd.get('journal'),activite_id:currentActivity(),exercice_annee:currentYear(),date_piece:fd.get('date'),libelle:fd.get('libelle'),reference_source:fd.get('reference')||null,statut:'brouillon',created_by:session.user.id}));
  bind('fEcriture',fd=>{const debit=Number(fd.get('debit')||0),credit=Number(fd.get('credit')||0);if(debit>0&&credit>0){toast('Une ligne ne peut pas être à la fois au débit et au crédit');return false}return insert('ecritures_comptables',{piece_id:fd.get('piece'),compte_id:fd.get('compte'),libelle:fd.get('libelle')||null,debit,credit})});
  document.querySelectorAll('[data-pay]').forEach(btn=>btn.onclick=async()=>{const col=C.collectes.find(x=>x.id===btn.dataset.pay);if(!col)return;const no='PAY-'+Date.now();const ok=await insert('paiements_planteurs',{numero_paiement:no,collecte_id:col.id,planteur_id:col.planteur_id,montant:Number(col.net_a_payer||0),moyen_paiement:'Caisse',statut:'valide',activite_id:col.activite_id,exercice_annee:col.exercice_annee,caissier_id:session.user.id});if(ok)await update('collectes',col.id,{statut_paiement:'paye'})})
};

const _renderV3=render;
render=function(){if(!pageAllowed(page))page='dashboard';_renderV3()};
